UpdateSourceArgs:
-c "#!/bin/bash
# Starts the game server by submitting the dedicated server web interface's start form.
# The server only spawns the game when that form is posted - there is no autostart setting.
# Run from PreStartStages with RunInBackground so it outlives the stage while waiting.
# Any setting left blank keeps whatever the web interface already has saved.
set -uo pipefail

HOST=\"\"; PORT=\"\"; USERNAME=\"admin\"; PASSWORD=\"\"; GAME_PORT=\"\"; SAVEGAME=\"\"; TIMEOUT=300
SERVER_NAME=\"\"; SERVER_PASS=\"\"; GAME_ADMIN_PASS=\"\"; MAX_PLAYERS=\"\"; LANGUAGE=\"\"
AUTOSAVE=\"\"; STATS=\"\"; PAUSE_EMPTY=\"\"; CROSSPLAY=\"\"
while [[ $# -gt 0 ]]; do
    case \"$1\" in
        --host) HOST=\"$2\"; shift 2 ;;
        --port) PORT=\"$2\"; shift 2 ;;
        --user) USERNAME=\"$2\"; shift 2 ;;
        --pass) PASSWORD=\"$2\"; shift 2 ;;
        --gameport) GAME_PORT=\"$2\"; shift 2 ;;
        --savegame) SAVEGAME=\"$2\"; shift 2 ;;
        --timeout) TIMEOUT=\"$2\"; shift 2 ;;
        --name) SERVER_NAME=\"$2\"; shift 2 ;;
        --password) SERVER_PASS=\"$2\"; shift 2 ;;
        --adminpass) GAME_ADMIN_PASS=\"$2\"; shift 2 ;;
        --maxplayers) MAX_PLAYERS=\"$2\"; shift 2 ;;
        --language) LANGUAGE=\"$2\"; shift 2 ;;
        --autosave) AUTOSAVE=\"$2\"; shift 2 ;;
        --statsinterval) STATS=\"$2\"; shift 2 ;;
        --pauseempty) PAUSE_EMPTY=\"$2\"; shift 2 ;;
        --crossplay) CROSSPLAY=\"$2\"; shift 2 ;;
        *) echo \"ERROR: unknown argument '$1'\"; exit 1 ;;
    esac
done
[[ -n \"$PORT\" ]] || { echo \"ERROR: --port is required\"; exit 1; }

JAR=\"$(mktemp)\"
trap 'rm -f \"$JAR\"' EXIT
UNCHECKED=$'\002'

# Reads the form into \"name<TAB>value\" lines. Fields differ between titles, so nothing is hardcoded.
# An unchecked box is reported as \002 so a setting can still switch it on.
parse_form() {
    sed -e 's/></>\n</g' \
    | awk '
        function attr(s, a,   r) {
            if (match(s, a \"[[:space:]]*=[[:space:]]*\\\"\")) {
                r = substr(s, RSTART + RLENGTH)
                return substr(r, 1, index(r, \"\\\"\") - 1)
            }
            return \"\001\"
        }
        /^<input/ {
            t = attr($0, \"type\"); n = attr($0, \"name\")
            if (n == \"\001\" || t == \"submit\" || t == \"button\" || t == \"reset\") next
            v = attr($0, \"value\"); if (v == \"\001\") v = \"\"
            if (t == \"checkbox\") { print n \"\t\" ($0 ~ /checked/ ? (v == \"\" ? \"on\" : v) : \"\002\"); next }
            print n \"\t\" v
            next
        }
        /^<select/ { sel = attr($0, \"name\"); chosen = \"\001\"; first = \"\001\"; next }
        /^<option/ && sel != \"\" {
            v = attr($0, \"value\")
            if (v == \"\001\") { v = $0; sub(/^<option[^>]*>/, \"\", v) }
            if (first == \"\001\") first = v
            if ($0 ~ /selected/ && chosen == \"\001\") chosen = v
            next
        }
        /^<\/select>/ && sel != \"\" {
            print sel \"\t\" (chosen != \"\001\" ? chosen : (first != \"\001\" ? first : \"\"))
            sel = \"\"; next
        }
    '
}

# The server binds one interface address, not the wildcard, so the loopback may not answer.
candidate_hosts() {
    if [[ -n \"$HOST\" ]]; then printf '%s\n' \"$HOST\"; return; fi
    printf '127.0.0.1\n'
    hostname -I 2>/dev/null | tr ' \t' '\n\n'
    ip -4 -o addr show scope global 2>/dev/null | awk '{ print $4 }' | cut -d/ -f1
}
mapfile -t CANDIDATES < <(candidate_hosts | grep -E '^[0-9]+(\.[0-9]+){3}$' | awk '!seen[$0]++')
[[ ${#CANDIDATES[@]} -gt 0 ]] || { echo \"ERROR: no local address could be found to reach the web interface on.\"; exit 1; }

echo \"Waiting for the dedicated server web interface on port ${PORT}...\"
FOUND=\"\"
deadline=$(( SECONDS + TIMEOUT ))
while (( SECONDS < deadline )); do
    for h in \"${CANDIDATES[@]}\"; do
        if curl -fsS -m 5 -o /dev/null \"http://${h}:${PORT}/index.html?lang=en\" 2>/dev/null; then FOUND=\"$h\"; break 2; fi
    done
    sleep 3
done
if [[ -z \"$FOUND\" ]]; then
    echo \"ERROR: the web interface did not come up within ${TIMEOUT}s, so the game server was not started.\"
    echo \"       Tried: ${CANDIDATES[*]}\"
    exit 1
fi
BASE=\"http://${FOUND}:${PORT}/index.html?lang=en\"
echo \"Web interface answered on ${FOUND}:${PORT}\"

if ! curl -fsS -m 15 -c \"$JAR\" -o /dev/null -X POST \"$BASE\" \
        --data-urlencode \"username=$USERNAME\" \
        --data-urlencode \"password=$PASSWORD\" \
        --data-urlencode \"login=Login\"; then
    echo \"ERROR: could not reach the web interface to log in.\"
    exit 1
fi

PAGE=\"$(curl -fsS -m 15 -b \"$JAR\" \"$BASE\" 2>/dev/null)\"
if [[ -z \"$PAGE\" ]]; then
    echo \"ERROR: the web interface returned nothing after logging in.\"
    exit 1
fi
# No form means the login was rejected.
if ! grep -q 'name=\"start_server\"\|name=\"stop_server\"' <<<\"$PAGE\"; then
    echo \"ERROR: the web interface rejected the admin username and password, so the game server was not started.\"
    echo \"       These come from the Admin Username and Admin Password settings on this instance.\"
    exit 1
fi
if grep -q 'name=\"stop_server\"' <<<\"$PAGE\"; then
    echo \"The game server is already running\"
    exit 0
fi

# Resend the form as served, overriding only the fields that have an AMP setting filled in.
ARGS=()
APPLIED=()
while IFS=$'\t' read -r name value; do
    [[ -n \"$name\" ]] || continue
    case \"$name\" in
        server_port)         [[ -n \"$GAME_PORT\" ]] && value=\"$GAME_PORT\" ;;
        savegame)            [[ -n \"$SAVEGAME\" ]] && value=\"$SAVEGAME\" ;;
        game_name)           [[ -n \"$SERVER_NAME\" ]] && { value=\"$SERVER_NAME\"; APPLIED+=(name); } ;;
        game_password)       [[ -n \"$SERVER_PASS\" ]] && { value=\"$SERVER_PASS\"; APPLIED+=(password); } ;;
        admin_password)      [[ -n \"$GAME_ADMIN_PASS\" ]] && { value=\"$GAME_ADMIN_PASS\"; APPLIED+=(adminpass); } ;;
        max_player)          [[ -n \"$MAX_PLAYERS\" ]] && { value=\"$MAX_PLAYERS\"; APPLIED+=(maxplayers); } ;;
        mp_language)         [[ -n \"$LANGUAGE\" ]] && { value=\"$LANGUAGE\"; APPLIED+=(language); } ;;
        auto_save_interval)  [[ -n \"$AUTOSAVE\" ]] && { value=\"$AUTOSAVE\"; APPLIED+=(autosave); } ;;
        stats_interval)      [[ -n \"$STATS\" ]] && { value=\"$STATS\"; APPLIED+=(stats); } ;;
        pause_game_if_empty) [[ -n \"$PAUSE_EMPTY\" ]] && { value=\"$PAUSE_EMPTY\"; APPLIED+=(pause); } ;;
        crossplay_allowed)
            case \"$CROSSPLAY\" in
                true)  value=\"on\"; APPLIED+=(crossplay) ;;
                false) APPLIED+=(crossplay); continue ;;
            esac ;;
    esac
    # An unchecked box submits nothing unless a setting switched it on.
    [[ \"$value\" == \"$UNCHECKED\" ]] && continue
    ARGS+=(--data-urlencode \"$name=$value\")
done < <(parse_form <<<\"$PAGE\")

if [[ ${#ARGS[@]} -eq 0 ]]; then
    echo \"ERROR: no settings could be read from the start form, so the game server was not started.\"
    exit 1
fi
ARGS+=(--data-urlencode \"start_server=Start\")
[[ ${#APPLIED[@]} -gt 0 ]] && echo \"Applied AMP settings: ${APPLIED[*]}\"

echo \"Starting the game server\"
if ! curl -fsS -m 60 -b \"$JAR\" -c \"$JAR\" -o /dev/null -X POST \"$BASE\" \"${ARGS[@]}\"; then
    echo \"ERROR: the start request failed.\"
    exit 1
fi

# The Stop button replacing Start means the game server is up.
deadline=$(( SECONDS + 120 ))
while (( SECONDS < deadline )); do
    sleep 3
    if curl -fsS -m 15 -b \"$JAR\" \"$BASE\" 2>/dev/null | grep -q 'name=\"stop_server\"'; then
        echo \"Game server started\"
        exit 0
    fi
done
echo \"ERROR: the game server did not report as started. Check the web interface on port ${PORT}.\"
exit 1
" fs-autostart --port {{$WebInterfacePort}} --user "{{AdminUsername}}" --pass "{{AdminPassword}}" --gameport {{$GamePort}} --savegame "{{AutoStartSavegame}}" --name "{{ServerName}}" --password "{{ServerPassword}}" --adminpass "{{GameAdminPassword}}" --maxplayers "{{MaxPlayers}}" --language "{{ServerLanguage}}" --autosave "{{AutoSaveInterval}}" --statsinterval "{{StatsInterval}}" --pauseempty "{{PauseWhenEmpty}}"
